    [Parameter]
    public EventCallback<string> OnSessionRevoked { get; set; }

    private string? _confirmingRevoke;

    private async Task RevokeConfirmedAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _confirmingRevoke = null;
        await OnSessionRevoked.InvokeAsync(sessionId);
    }
}
"}

{"path": "/tmp/sv-ece8312d5ff14b1eb1e896081297cb9e/Components/Pages/Settings/SecuritySection.razor", "file_text": "@using sv_ece8312d5ff14b1eb1e896081297cb9e.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h3 class="mb-4">Security Settings</h3>

    @if (_loading)
    {
        <div class="text-center py-4">
            <div class="spinner-border" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else
    {
        <ChangePasswordPanel />

        <div class="card mb-4">
            <div class="card-body">
                <h5 class="card-title mb-3">Two-Factor Authentication</h5>
                <div class="d-flex align-items-center gap-3">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="twoFactor"
                               checked="@_twoFactorEnabled" disabled />
                        <label class="form-check-label" for="twoFactor">Two-Factor Authentication</label>
                    </div>
                    @if (_twoFactorEnabled)
                    {
                        <span class="badge bg-success">Enabled</span>
                    }
                    else
                    {
                        <span class="badge bg-warning text-dark">Disabled</span>
                    }
                </div>
                @if (_lastPasswordChange.HasValue)
                {
                    <small class="text-muted d-block mt-2">
                        Last password change: @_lastPasswordChange.Value.ToString("f")
                    </small>
                }
            </div>
        </div>

        <ActiveSessionsTable Sessions="_sessions" OnSessionRevoked="HandleSessionRevoked" />
    }
</div>

@code {
    private bool _loading = true;
    private bool _twoFactorEnabled;
    private DateTime? _lastPasswordChange;
    private List<ActiveSession> _sessions = new();

    protected override async Task OnInitializedAsync()
    {
        await LoadAsync();
    }

    private async Task LoadAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = settings.TwoFactorEnabled;
        _lastPasswordChange = settings.LastPasswordChange;
        _sessions = settings.Sessions;
        _loading = false;
    }

    private void HandleSessionRevoked(string sessionId)
    {
        _sessions = _sessions.Where(s => s.Id != sessionId).ToList();
    }
}
"}

{"path": "/tmp/sv-ece8312d5ff14b1eb1e896081297cb9e/Components/Pages/Settings/AppearanceSection.razor", "file_text": "@using sv_ece8312d5ff14b1eb1e896081297cb9e.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h3 class="mb-4">Appearance Settings</h3>

    @if (_loading)
    {
        <div class="text-center py-4">
            <div class="spinner-border" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else
    {
        <div class="row">
            <div class="col-md-7">
                <div class="card mb-4">
                    <div class="card-body">
                        <h5 class="card-title mb-3">Theme</h5>
                        @foreach (var theme in new[] { "Light", "Dark", "System" })
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="radio" name="theme"
                                       id="@($"theme-{theme}")" value="@theme"
                                       checked="@(_theme == theme)"
                                       @onchange="() => _theme = theme" />
                                <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                            </div>
                        }
                    </div>
                </div>

                <div class="card mb-4">
                    <div class="card-body">
                        <h5 class="card-title mb-3">Font Size</h5>
                        @foreach (var size in new[] { "Small", "Medium", "Large" })
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="radio" name="fontSize"
                                       id="@($"fs-{size}")" value="@size"
                                       checked="@(_fontSize == size)"
                                       @onchange="() => _fontSize = size" />
                                <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                            </div>
                        }
                    </div>
                </div>

                <div class="card mb-4">
                    <div class="card-body">
                        <h5 class="card-title mb-3">Language</h5>
                        <select class="form-select" @bind="_language">
                            <option value="en">English</option>
                            <option value="es">Spanish</option>
                            <option value="fr">French</option>
                            <option value="de">German</option>
                            <option value="ja">Japanese</option>
                            <option value="zh">Chinese</option>
                        </select>
                    </div>
                </div>

                <div class="card mb-4">
                    <div class="card-body">
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                            <label class="form-check-label" for="compactMode">Compact Mode</label>
                        </div>
                    </div>
                </div>

                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                    @if (_saving)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                    }
                    Save
                </button>

                @if (_showSuccess)
                {
                    <div class="alert alert-success mt-3 d-flex align-items-center" role="alert">
                        <span class="me-2">✓</span> Appearance settings saved!
                    </div>
                }
            </div>

            <div class="col-md-5">
                <div class="card sticky-top" style="top: 1rem;">
                    <div class="card-header">
                        <h5 class="mb-0">Live Preview</h5>
                    </div>
                    <div class="card-body @PreviewBackgroundClass" style="@PreviewStyle">
                        <h6 style="@PreviewFontStyle">Sample Heading</h6>
                        <p style="@PreviewFontStyle" class="@PreviewTextClass">
                            This is how your content will look with the selected settings.
                        </p>
                        <div class="d-flex gap-2 @(_compactMode ? "py-1" : "py-2")">
                            <span class="badge @PreviewBadgeClass">Tag 1</span>
                            <span class="badge @PreviewBadgeClass">Tag 2</span>
                            <span class="badge @PreviewBadgeClass">Tag 3</span>
                        </div>
                        <button class="btn btn-sm @PreviewButtonClass mt-2" style="@PreviewFontStyle">
                            Sample Button
                        </button>
                        <div class="mt-2">
                            <small class="@PreviewTextClass">
                                Theme: @_theme | Size: @_fontSize | Compact: @(_compactMode ? "On" : "Off")
                            </small>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;
    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _showSuccess = false;
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _saving = false;
        _showSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }

    private string PreviewStyle => _theme == "Dark"
        ? "min-height:200px; transition: all 0.3s ease;"
        : "min-height:200px; transition: all 0.3s ease;";

    private string PreviewFontStyle => _fontSize switch
    {
        "Small" => "font-size: 0.8rem;",
        "Large" => "font-size: 1.2rem;",
        _ => "font-size: 1rem;"
    };

    private string PreviewBackgroundClass => _theme switch
    {
        "Dark" => "bg-dark",
        "System" => "bg-light border",
        _ => "bg-white border"
    };

    private string PreviewTextClass => _theme == "Dark" ? "text-light" : "text-dark";

    private string PreviewBadgeClass => _theme == "Dark" ? "bg-light text-dark" : "bg-secondary";

    private string PreviewButtonClass => _theme == "Dark" ? "btn-outline-light" : "btn-outline-primary";
}
"}

